WITH with_gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM web_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.session_start_flag, s.session_no, (SELECT MIN(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS min_web_event_duration_sec FROM sessionized s ORDER BY id DESC NULLS FIRST, event_time LIMIT 10
